using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;
public static class PlantRebuild {
 [Serializable]public class Spec{public string id,kind,family,plant;public int stage;}
 [Serializable]public class Input{public Spec[] assets;public Dictionary<string,string> aliases;}
 static Camera camera;static Material material;static System.Text.StringBuilder report=new System.Text.StringBuilder();
 static void Check(bool yes,string message){if(!yes)throw new Exception(message);}
 static void MeshAsset(Mesh mesh,string path){var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null)AssetDatabase.CreateAsset(mesh,path);else {EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);}}
 static Bounds BoundsOf(GameObject obj){var bounds=new Bounds();bool first=true;foreach(var skin in obj.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(s=>s.name=="Prop_LOD0")){var bake=new Mesh();skin.BakeMesh(bake);foreach(var vertex in bake.vertices){var v=obj.transform.InverseTransformPoint(skin.transform.TransformPoint(vertex));if(first){bounds=new Bounds(v,Vector3.zero);first=false;}else bounds.Encapsulate(v);}UnityEngine.Object.DestroyImmediate(bake);}Check(!first,"No LOD0 bounds");return bounds;}
 static void Studio(){
  camera=new GameObject("BotanicalReviewCamera").AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.nearClipPlane=.01f;camera.farClipPlane=30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.075f,.09f,.075f);
  RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.46f,.48f,.43f);var key=new GameObject("Key").AddComponent<Light>();key.type=LightType.Directional;key.color=new Color(1,.96f,.87f);key.intensity=1.1f;key.transform.rotation=Quaternion.Euler(38,-35,0);var fill=new GameObject("Fill").AddComponent<Light>();fill.type=LightType.Directional;fill.color=new Color(.75f,.83f,1);fill.intensity=.4f;fill.transform.rotation=Quaternion.Euler(20,135,0);
 }
 static void Picture(GameObject obj,string file,int size,Vector3 direction,bool alpha=false,Bounds? common=null){
  var bounds=common??BoundsOf(obj);camera.orthographicSize=Mathf.Max(.065f,Mathf.Max(bounds.size.y,bounds.size.x)*.66f);var focus=obj.transform.TransformPoint(bounds.center);camera.transform.position=focus+direction.normalized*4;camera.transform.LookAt(focus);var bg=camera.backgroundColor;if(alpha)camera.backgroundColor=new Color(0,0,0,0);
  var rt=new RenderTexture(size,size,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var pic=new Texture2D(size,size,alpha?TextureFormat.RGBA32:TextureFormat.RGB24,false);pic.ReadPixels(new Rect(0,0,size,size),0,0);pic.Apply();Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllBytes(file,pic.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;camera.backgroundColor=bg;UnityEngine.Object.DestroyImmediate(pic);rt.Release();UnityEngine.Object.DestroyImmediate(rt);
 }
 static Material Surface(){
  foreach(var name in new[]{"Albedo","Normal"}){var importer=(TextureImporter)AssetImporter.GetAtPath("Assets/BotanicalTextures/"+name+".png");Check(importer!=null,"Missing surface map");importer.sRGBTexture=name=="Albedo";importer.maxTextureSize=2048;importer.npotScale=TextureImporterNPOTScale.None;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.anisoLevel=4;importer.wrapMode=TextureWrapMode.Clamp;if(name=="Normal")importer.textureType=TextureImporterType.NormalMap;importer.SaveAndReimport();}
  const string path="Assets/BotanicalSurface.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(Shader.Find("Delve/BotanicalSurface"));AssetDatabase.CreateAsset(mat,path);}mat.shader=Shader.Find("Delve/BotanicalSurface");Check(mat.shader.isSupported,"Botanical shader unsupported");mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/BotanicalTextures/Albedo.png");mat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/BotanicalTextures/Normal.png"));mat.SetFloat("_BumpScale",.32f);EditorUtility.SetDirty(mat);return mat;
 }
 static void Process(Spec spec){
  var importer=(ModelImporter)AssetImporter.GetAtPath("Assets/Models/"+spec.id+".fbx");Check(importer!=null,"Model missing "+spec.id);importer.isReadable=true;importer.importCameras=false;importer.importLights=false;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.SaveAndReimport();
  string pp="Assets/Generated/"+spec.id+".prefab";var source=AssetDatabase.LoadAssetAtPath<GameObject>(pp);Check(source!=null,"Prefab missing "+spec.id);var obj=UnityEngine.Object.Instantiate(source);obj.name=spec.id;var animator=obj.GetComponent<Animator>();Check(animator!=null&&animator.runtimeAnimatorController!=null,"Controller missing");animator.enabled=false;var clips=animator.runtimeAnimatorController.animationClips;Check(clips.Length==(spec.kind=="plant"?3:1),"Clip count "+spec.id);
  if(spec.kind=="plant"){var controller=(AnimatorController)animator.runtimeAnimatorController;var machine=controller.layers[0].stateMachine;machine.defaultState=machine.states.Single(s=>s.state.name=="Sway").state;animator.cullingMode=AnimatorCullingMode.CullUpdateTransforms;EditorUtility.SetDirty(controller);}
  var skins=obj.GetComponentsInChildren<SkinnedMeshRenderer>(true);Check(skins.Length==3,"LOD count "+spec.id);var lods=new LOD[3];var counts=new int[3];var bake=new Mesh();
  for(int level=0;level<3;level++){var skin=skins.Single(s=>s.name=="Prop_LOD"+level);skin.sharedMaterial=material;var mesh=skin.sharedMesh;Check(mesh!=null&&mesh.vertexCount>0,"Mesh missing");counts[level]=mesh.triangles.Length/3;Check(mesh.colors.Length==mesh.vertexCount,"Missing variation");Check(mesh.tangents.Length==mesh.vertexCount,"Missing tangents");Check(mesh.uv.All(p=>p.x>.003f&&p.x<.997f&&p.y>.003f&&p.y<.997f),"UV atlas bounds");Check(mesh.boneWeights.All(w=>Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)<.01f),"Weights");skin.updateWhenOffscreen=false;skin.gameObject.SetActive(true);skin.enabled=true;skin.BakeMesh(bake);skin.localBounds=bake.bounds;lods[level]=new LOD(new[]{.3f,.12f,.015f}[level],new Renderer[]{skin});}
  Check(counts[0]<22000&&counts[1]<counts[0]&&counts[2]<counts[1],"Triangle budget "+spec.id+" "+String.Join("/",counts));
  float motion=0;foreach(var clip in clips){Check(clip.events.Length==0,"Gameplay callbacks");Vector3[] start=null;foreach(float t in new[]{0f,.25f,.5f,.75f,1f}){clip.SampleAnimation(obj,clip.length*t);foreach(var skin in skins){skin.BakeMesh(bake);Check(bake.vertices.All(v=>!float.IsNaN(v.x)&&!float.IsInfinity(v.sqrMagnitude)&&v.sqrMagnitude<10),"Invalid deformation");if(skin.name=="Prop_LOD0"){if(start==null)start=bake.vertices;else if(clip.name.EndsWith("Sway")){var end=bake.vertices;for(int i=0;i<end.Length;i++)motion=Mathf.Max(motion,(end[i]-start[i]).magnitude);}}}}}
  if(spec.kind=="plant")Check(motion>.00001f,"Plant sway inactive "+spec.id);clips.First(c=>c.name.EndsWith("Idle")).SampleAnimation(obj,0);
  var bounds=BoundsOf(obj);Check(bounds.min.y>-.035f&&bounds.size.x<1.5f&&bounds.size.y<1.2f&&bounds.size.z<1.5f,"Plant footprint "+spec.id+" "+bounds);var collider=obj.GetComponent<BoxCollider>();if(spec.kind=="plant"){Check(collider!=null,"Missing harvesting collider");Check(obj.tag=="T_Block"&&obj.layer==16,"Block identification");collider.center=bounds.center;collider.size=bounds.size+Vector3.one*.012f;Check(!collider.isTrigger,"Harvest ray needs solid collider");Physics.SyncTransforms();RaycastHit hit;Check(Physics.Raycast(bounds.center+Vector3.forward*2,Vector3.back,out hit,4,1<<16)&&hit.collider==collider,"Harvest interaction ray");var socket=obj.transform.Find("HarvestSocket");Check(socket!=null,"Harvest socket");socket.localPosition=bounds.center;}
  var group=obj.GetComponent<LODGroup>();group.SetLODs(lods);group.localReferencePoint=bounds.center;group.size=Mathf.Max(bounds.size.x,Mathf.Max(bounds.size.y,bounds.size.z));group.ForceLOD(-1);animator.enabled=true;PrefabUtility.SaveAsPrefabAsset(obj,pp);
  // Update paired inventory/drop representation without changing its address.
  var skin0=skins.Single(s=>s.name=="Prop_LOD0");skin0.BakeMesh(bake);var dropMesh=UnityEngine.Object.Instantiate(bake);var vertices=dropMesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]=obj.transform.InverseTransformPoint(skin0.transform.TransformPoint(vertices[i]))-bounds.center;dropMesh.vertices=vertices;dropMesh.RecalculateBounds();string mp="Assets/Generated/"+spec.id+"_Drop.asset";MeshAsset(dropMesh,mp);
  string dp="Assets/Generated/"+spec.id+"_Drop.prefab";var drop=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(dp));drop.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(mp);drop.GetComponent<MeshRenderer>().sharedMaterial=material;var dc=drop.GetComponent<BoxCollider>();dc.center=Vector3.zero;dc.size=bounds.size+Vector3.one*.012f;PrefabUtility.SaveAsPrefabAsset(drop,dp);UnityEngine.Object.DestroyImmediate(drop);
  animator.enabled=false;group.ForceLOD(0);var folder="../Review/"+spec.id;Picture(obj,folder+"/hero.png",1024,new Vector3(1.2f,.7f,2.5f));Picture(obj,folder+"/side.png",768,new Vector3(-1.6f,.35f,2));Picture(obj,folder+"/top.png",768,new Vector3(.2f,2.5f,1.2f));Picture(obj,"../Delivery/UIAtlases/ItemIconAtlas/"+spec.id+".png",256,new Vector3(1.2f,.7f,2.5f),true);
  string family=spec.plant??spec.family;if(spec.kind=="plant"){float h=family=="Bramble"?.95f:family=="Yarrow"?.7f:family=="Thyme"?.4f:.32f;Picture(obj,folder+"/stage.png",512,new Vector3(1.2f,.7f,2.5f),false,new Bounds(new Vector3(0,h*.5f,0),new Vector3(h,h,h*.75f)));}
  if(spec.stage==3&&spec.kind=="plant"){var clip=clips.Single(c=>c.name.EndsWith("Sway"));for(int frame=0;frame<12;frame++){clip.SampleAnimation(obj,clip.length*frame/12);Picture(obj,folder+"/sway-"+frame.ToString("D2")+".png",512,new Vector3(1.2f,.7f,2.5f),false,bounds);}}
  report.AppendLine(spec.id+" PASS LOD triangles="+String.Join("/",counts)+" clips="+clips.Length+" swayMeters="+motion.ToString("F5")+" footprint="+bounds.size+" materials=1 drop=updated"+(spec.kind=="plant"?" harvestRay=PASS default=Sway":""));UnityEngine.Object.DestroyImmediate(bake);UnityEngine.Object.DestroyImmediate(obj);
 }
 static void Aliases(){foreach(string family in new[]{"Bramble","Yarrow","Thyme","Mooncap"}){var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Generated/plantedDelve"+family+"3Harvest.prefab");var obj=UnityEngine.Object.Instantiate(original);obj.name="plantedDelve"+family+"3HarvestPlayer";PrefabUtility.SaveAsPrefabAsset(obj,"Assets/Generated/"+obj.name+".prefab");UnityEngine.Object.DestroyImmediate(obj);}}
 static void Bundle(){var prefabs=Directory.GetFiles("Assets/Generated","*.prefab").OrderBy(s=>s).ToArray();var addresses=prefabs.Select(Path.GetFileNameWithoutExtension).ToArray();Check(addresses.Length==229,"Address contract changed "+addresses.Length);var build=new AssetBundleBuild{assetBundleName="forestprops.unity3d",assetNames=prefabs,addressableNames=addresses};Directory.CreateDirectory("../Bundle");Check(BuildPipeline.BuildAssetBundles("../Bundle",new[]{build},BuildAssetBundleOptions.ChunkBasedCompression|BuildAssetBundleOptions.ForceRebuildAssetBundle,BuildTarget.StandaloneWindows64)!=null,"Bundle failure");File.Copy("../Bundle/forestprops.unity3d","../Delivery/Resources/forestprops.unity3d",true);File.WriteAllLines("../Reports/bundle-addresses.txt",addresses);report.AppendLine("BUNDLE all "+addresses.Length+" original addresses; botanical models updated; other props preserved");}
 public static void RebuildBundle(){try{AssetDatabase.Refresh();Bundle();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void ProbeLoad(){var log=new System.Text.StringBuilder();foreach(string path in new[]{"../Delivery/Resources/forestprops.unity3d","../SourceBackup/src/ZDelvePresentation/Resources/forestprops.unity3d","D:/Projects/ChatGPT/7 days to delve/artifacts/batch-11/art/Bundle/batcheleven.unity3d"}){var b=AssetBundle.LoadFromFile(Path.GetFullPath(path));log.AppendLine(path+" "+(b==null?"FAIL":"PASS "+b.GetAllAssetNames().Length));if(b!=null)b.Unload(true);}File.WriteAllText("../Reports/load-probe.txt",log.ToString());EditorApplication.Exit(0);}
 public static void Run(){try{AssetDatabase.Refresh();Studio();material=Surface();var input=JsonUtility.FromJson<Input>(File.ReadAllText("../plants.json"));foreach(var spec in input.assets){File.WriteAllText("../Reports/unity-progress.txt","BUILDING "+spec.id);Process(spec);}Aliases();AssetDatabase.SaveAssets();Bundle();File.WriteAllText("../Reports/unity-validation.txt","PASS\n"+report+"\nLIMIT: offline Unity structural, deformation, collider-ray and render checks. In-game growth, harvesting rewards, dense-scene FPS and multiplayer were not run.");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);File.WriteAllText("../Reports/unity-validation.txt","FAIL\n"+e+"\n"+report);EditorApplication.Exit(1);}}
 public static void VerifyBundle(){AssetBundle bundle=null;try{
  bundle=AssetBundle.LoadFromFile(Path.GetFullPath("../Delivery/Resources/forestprops.unity3d"));Check(bundle!=null,"Cannot reopen delivered bundle");var addresses=File.ReadAllLines("../Reports/bundle-addresses.txt");Check(addresses.Length==229&&bundle.GetAllAssetNames().Length==229,"Serialized address count");
  foreach(var address in addresses){var prefab=bundle.LoadAsset<GameObject>(address);Check(prefab!=null,"Serialized prefab missing "+address);foreach(var renderer in prefab.GetComponentsInChildren<Renderer>(true))Check(renderer.sharedMaterials.All(m=>m!=null&&m.shader!=null),"Serialized material missing "+address);}
  var input=JsonUtility.FromJson<Input>(File.ReadAllText("../plants.json"));int clips=0;
  foreach(var spec in input.assets){var obj=UnityEngine.Object.Instantiate(bundle.LoadAsset<GameObject>(spec.id));var skins=obj.GetComponentsInChildren<SkinnedMeshRenderer>(true);Check(skins.Length==3&&skins.All(s=>s.sharedMaterial.shader.name=="Delve/BotanicalSurface"&&s.sharedMaterial.shader.isSupported&&s.sharedMaterial.mainTexture!=null&&s.sharedMaterial.GetTexture("_BumpMap")!=null),"Serialized botanical surface "+spec.id);var animator=obj.GetComponent<Animator>();var motions=animator.runtimeAnimatorController.animationClips;clips+=motions.Length;Check(motions.All(c=>c.events.Length==0),"Serialized gameplay event");if(spec.kind=="plant"){animator.Update(0);Check(animator.GetCurrentAnimatorStateInfo(0).IsName("Sway"),"Serialized default sway state "+spec.id);Check(obj.GetComponent<BoxCollider>()!=null&&!obj.GetComponent<BoxCollider>().isTrigger,"Serialized harvest collider");}UnityEngine.Object.DestroyImmediate(obj);}
  Check(clips==58,"Serialized clip coverage");File.WriteAllText("../Reports/bundle-load-validation.txt","PASS reopened shipped bundle; 229 prefab addresses and material references resolved; 26 botanical models have supported shader, albedo and normal; 16 default Sway states and solid harvesting colliders; 58 clips, zero gameplay callbacks. Offline Unity check only.\n");bundle.Unload(true);EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("../Reports/bundle-load-validation.txt","FAIL\n"+e);if(bundle!=null)bundle.Unload(true);EditorApplication.Exit(1);}}
}
